218:     pub fn calculate_state_digest(
219:         problem_digest: &str,
220:         parent_digest: &str,
221:         step_idx: usize,
222:         sec: &[BigRational],
223:         defect: &BigRational,
224:     ) -> String {
225:         let mut hasher = Sha256::new();
226:         hasher.update(b"SG_STATE_V1:");
227:         hasher.update(problem_digest.as_bytes());
228:         hasher.update(b":PARENT:");
229:         hasher.update(parent_digest.as_bytes());
230:         hasher.update(b":STEP:");
231:         hasher.update(step_idx.to_string().as_bytes());
232:         hasher.update(b":SECTION:");
233:         for s in sec {
234:             hasher.update(s.to_string().as_bytes());
235:             hasher.update(b",");
236:         }
237:         hasher.update(b":DEFECT:");
238:         hasher.update(defect.to_string().as_bytes());
239:         format!("{:x}", hasher.finalize())
240:     }
