242:     pub fn compute_defect(problem: &SymbolGameProblem, sec: &[BigRational]) -> BigRational {
243:         let mut total = BigRational::zero();
244:         for (i, edge) in problem.edges.iter().enumerate() {
245:             let u_idx = problem.vertices.iter().position(|v| v == &edge.u).unwrap();
246:             let v_idx = problem.vertices.iter().position(|v| v == &edge.v).unwrap();
247:             let diff = &sec[v_idx] - &sec[u_idx];
248:             let residual = &problem.initial_claims[i] - diff;
249:             let abs_res = if residual.is_negative() {
250:                 -residual
251:             } else {
252:                 residual
253:             };
254:             total += &edge.weight * abs_res;
255:         }
256:         total
257:     }
