265:         for (i, edge) in self.problem.edges.iter().enumerate() {
266:             let u_idx = self.problem.vertices.iter().position(|v| v == &edge.u).unwrap();
267:             let v_idx = self.problem.vertices.iter().position(|v| v == &edge.v).unwrap();
268:             let diff = &sec[v_idx] - &sec[u_idx];
269:             residuals.push(&self.problem.initial_claims[i] - diff);
