274:     /// Verifies the three Lean soundness hypotheses for weak duality:
275:     /// 1. Divergence condition: B^T z = 0 at every vertex.
276:     /// 2. Weight bound: |z_e| <= w_e for every edge.
277:     /// 3. Zero duality gap: <z, r> == ||r||_{1,w}.
278:     pub fn verify_dual_witness(
279:         &self,
280:         dual: &[BigRational],
281:         sec: &[BigRational],
282:     ) -> Result<(), HostRefusalCode> {
283:         let n_edges = self.problem.edges.len();
284:         if dual.len() != n_edges || sec.len() != self.problem.vertices.len() {
285:             return Err(HostRefusalCode::FormatViolation);
286:         }
287: 
288:         // 1. Divergence check at each vertex: sum_{in} z_e - sum_{out} z_e = 0
289:         let n_verts = self.problem.vertices.len();
290:         let mut divergences = vec![BigRational::zero(); n_verts];
291:         for (e_idx, edge) in self.problem.edges.iter().enumerate() {
292:             let u_idx = self.problem.vertices.iter().position(|v| v == &edge.u).unwrap();
293:             let v_idx = self.problem.vertices.iter().position(|v| v == &edge.v).unwrap();
294:             divergences[v_idx] += &dual[e_idx];
295:             divergences[u_idx] -= &dual[e_idx];
296:         }
297: 
298:         for (v_idx, div) in divergences.iter().enumerate() {
299:             if !div.is_zero() {
300:                 return Err(HostRefusalCode::DualNotPerpendicular {
301:                     vertex: self.problem.vertices[v_idx].clone(),
302:                     divergence: div.to_string(),
303:                 });
304:             }
305:         }
306: 
307:         // 2. Weight bound: |z_e| <= w_e
308:         for (e_idx, edge) in self.problem.edges.iter().enumerate() {
309:             let z_val = &dual[e_idx];
310:             let abs_z = if z_val.is_negative() {
311:                 -z_val.clone()
312:             } else {
313:                 z_val.clone()
314:             };
315:             if abs_z > edge.weight {
316:                 return Err(HostRefusalCode::DualExceedsWeight {
317:                     edge_index: e_idx,
318:                     value: z_val.to_string(),
319:                     weight: edge.weight.to_string(),
320:                 });
321:             }
322:         }
323: 
324:         // 3. Zero duality gap: sum_e z_e * r_e == ||r||_{1,w}
325:         let residuals = self.compute_residuals(sec);
326:         let defect = Self::compute_defect(&self.problem, sec);
327: 
328:         let mut pairing = BigRational::zero();
329:         for (e_idx, res) in residuals.iter().enumerate() {
330:             pairing += &dual[e_idx] * res;
331:         }
332: 
333:         if pairing != defect {
334:             return Err(HostRefusalCode::DualityGapDetected {
335:                 pairing: pairing.to_string(),
336:                 defect: defect.to_string(),
337:             });
338:         }
339: 
340:         Ok(())
341:     }
342: 
343:     /// Evaluates an untrusted proposal fail-closed.
344:     pub fn process_proposal(&mut self, proposal: &UntrustedProposal) -> HostVerdict {
345:         // 1. FW-PROBLEM-PIN: Problem digest must match exactly
346:         if proposal.problem_digest != self.problem.digest {
347:             return self.refuse(HostRefusalCode::ProblemDigestMismatch {
348:                 expected: self.problem.digest.clone(),
349:                 found: proposal.problem_digest.clone(),
350:             });
351:         }
352: 
353:         // 2. FW-PARENT-PIN: Parent state digest must match current tip
354:         if proposal.parent_state_digest != self.current_state_digest {
355:             return self.refuse(HostRefusalCode::ParentStateMismatch {
356:                 expected: self.current_state_digest.clone(),
357:                 found: proposal.parent_state_digest.clone(),
358:             });
359:         }
360: 
361:         if !proposal.rationale.chars().all(|c| {
362:             matches!(c as u32, 32..=126 | 0x0391..=0x03A9 | 0x03B1..=0x03C9
363:                 | 0x2192 | 0x22A2 | 0x22A5 | 0x2261)
364:         }) {
365:             return self.refuse(HostRefusalCode::CarrierViolation);
366:         }
367:         let next_step = self.step_counter + 1;
368:         let event_id = format!("ev_{:04}_{:?}", next_step, proposal.op);
369:         let parent_event_id = self.history.last().map(|e| e.event_id.clone());
370: 
371:         match proposal.op {
372:             HostMoveOp::Cut => {
373:                 let candidate_section = match &proposal.proposed_section {
374:                     Some(sec) if sec.len() == self.problem.vertices.len() => sec,
375:                     _ => return self.refuse(HostRefusalCode::FormatViolation),
376:                 };
377: 
378:                 let defect_before = self.section_defect();
379:                 let defect_after = Self::compute_defect(&self.problem, candidate_section);
380: 
381:                 // Monotonic descent check: defect must not increase
382:                 if defect_after > defect_before {
383:                     return self.refuse(HostRefusalCode::DefectIncrease {
384:                         before: defect_before.to_string(),
385:                         after: defect_after.to_string(),
386:                     });
387:                 }
388: 
389:                 // Compute host post-state digest
390:                 let host_post_digest = Self::calculate_state_digest(
391:                     &self.problem.digest,
392:                     &self.current_state_digest,
393:                     next_step,
394:                     candidate_section,
395:                     &defect_after,
396:                 );
397: 
398:                 // Validate proposer claimed post-state digest
399:                 if host_post_digest != proposal.claimed_post_state_digest {
400:                     return self.refuse(HostRefusalCode::PostStateDigestMismatch {
401:                         host_digest: host_post_digest,
402:                         claimed_digest: proposal.claimed_post_state_digest.clone(),
403:                     });
404:                 }
405: 
406:                 // Commit state
407:                 self.section = candidate_section.clone();
408:                 self.step_counter = next_step;
409:                 self.current_state_digest = host_post_digest.clone();
410: 
411:                 let ev = VerifiedEvent {
412:                     event_id: event_id.clone(),
413:                     parent_event_id,
414:                     problem_digest: self.problem.digest.clone(),
415:                     parent_state_digest: proposal.parent_state_digest.clone(),
416:                     post_state_digest: host_post_digest.clone(),
417:                     op: HostMoveOp::Cut,
418:                     verified_defect: defect_after.clone(),
419:                     details: format!("CUT accepted: defect reduced from {} to {}", defect_before, defect_after),
420:                     section_snapshot: self.section.clone(),
421:                 };
422:                 self.history.push(ev);
423: 
424:                 HostVerdict {
425:                     admitted: true,
426:                     refusal_code: None,
427:                     reason: None,
428:                     post_state_digest: Some(host_post_digest),
429:                     verified_defect: Some(defect_after),
430:                     event_id: Some(event_id),
431:                 }
432:             }
433: 
434:             HostMoveOp::Verify => {
435:                 let target_prop = proposal.target_property.as_deref().unwrap_or("");
436:                 let cur_defect = self.section_defect();
437: 
438:                 if target_prop == "ZERO_OBSTRUCTION" {
439:                     if !cur_defect.is_zero() {
440:                         return self.refuse(HostRefusalCode::NonzeroObstruction {
441:                             defect: cur_defect.to_string(),
442:                         });
443:                     }
444:                 } else if target_prop == "DUAL_WITNESS" {
445:                     let dual = match &proposal.dual_witness {
446:                         Some(d) if d.len() == self.problem.edges.len() => d,
447:                         _ => return self.refuse(HostRefusalCode::FormatViolation),
448:                     };
449:                     if let Err(refusal) = self.verify_dual_witness(dual, &self.section) {
450:                         return self.refuse(refusal);
451:                     }
452:                 } else {
453:                     return self.refuse(HostRefusalCode::FormatViolation);
454:                 }
455: 
456:                 let host_post_digest = Self::calculate_state_digest(
457:                     &self.problem.digest,
458:                     &self.current_state_digest,
459:                     next_step,
460:                     &self.section,
461:                     &cur_defect,
462:                 );
463: 
464:                 if host_post_digest != proposal.claimed_post_state_digest {
465:                     return self.refuse(HostRefusalCode::PostStateDigestMismatch {
466:                         host_digest: host_post_digest,
467:                         claimed_digest: proposal.claimed_post_state_digest.clone(),
468:                     });
469:                 }
470: 
471:                 self.step_counter = next_step;
472:                 self.current_state_digest = host_post_digest.clone();
473:                 let ev = VerifiedEvent {
474:                     event_id: event_id.clone(),
475:                     parent_event_id,
476:                     problem_digest: self.problem.digest.clone(),
477:                     parent_state_digest: proposal.parent_state_digest.clone(),
478:                     post_state_digest: host_post_digest.clone(),
479:                     op: HostMoveOp::Verify,
480:                     verified_defect: cur_defect.clone(),
481:                     details: format!("VERIFY '{}' accepted with defect {}", target_prop, cur_defect),
482:                     section_snapshot: self.section.clone(),
483:                 };
484:                 self.history.push(ev);
485: 
486:                 HostVerdict {
487:                     admitted: true,
488:                     refusal_code: None,
489:                     reason: None,
490:                     post_state_digest: Some(host_post_digest),
491:                     verified_defect: Some(cur_defect),
492:                     event_id: Some(event_id),
493:                 }
494:             }
495: 
496:             HostMoveOp::Assert => {
497:                 // Problem claims are immutable; uncertified assert refused
498:                 self.refuse(HostRefusalCode::UnlicensedProblemMutation)
499:             }
500: 
501:             HostMoveOp::Retract => {
502:                 let target_ev = match &proposal.target_event_id {
503:                     Some(tid) => tid,
504:                     None => return self.refuse(HostRefusalCode::FormatViolation),
505:                 };
506: 
507:                 let found_idx = self.history.iter().position(|e| &e.event_id == target_ev);
508:                 let idx = match found_idx {
509:                     Some(i) => i,
510:                     None => {
511:                         return self.refuse(HostRefusalCode::EventNotFound {
512:                             event_id: target_ev.clone(),
513:                         })
514:                     }
515:                 };
516: 
517:                 let restored = if idx == 0 {
518:                     vec![BigRational::zero(); self.problem.vertices.len()]
519:                 } else {
520:                     self.history[idx - 1].section_snapshot.clone()
521:                 };
522:                 let defect = Self::compute_defect(&self.problem, &restored);
523:                 let post_digest = Self::calculate_state_digest(
524:                     &self.problem.digest, &self.current_state_digest, next_step, &restored, &defect,
525:                 );
526:                 if post_digest != proposal.claimed_post_state_digest {
527:                     return self.refuse(HostRefusalCode::PostStateDigestMismatch {
528:                         host_digest: post_digest,
529:                         claimed_digest: proposal.claimed_post_state_digest.clone(),
530:                     });
531:                 }
532:                 self.history.push(VerifiedEvent {
533:                     event_id: event_id.clone(), parent_event_id,
534:                     problem_digest: self.problem.digest.clone(),
535:                     parent_state_digest: self.current_state_digest.clone(),
536:                     post_state_digest: post_digest.clone(), op: HostMoveOp::Retract,
537:                     verified_defect: defect,
538:                     details: format!("Restored state before {}; prior events retained", target_ev),
539:                     section_snapshot: restored.clone(),
540:                 });
541:                 self.section = restored;
542:                 self.current_state_digest = post_digest;
543:                 self.step_counter = next_step;
544: 
545:                 HostVerdict {
546:                     admitted: true,
547:                     refusal_code: None,
548:                     reason: None,
549:                     post_state_digest: Some(self.current_state_digest.clone()),
550:                     verified_defect: Some(self.section_defect()),
551:                     event_id: Some(event_id),
552:                 }
553:             }
554:         }
555:     }
556: 
557:     fn refuse(&mut self, code: HostRefusalCode) -> HostVerdict {
558:         let reason = code.to_string();
559:         self.refusals.push(code.clone());
560:         HostVerdict {
561:             admitted: false,
562:             refusal_code: Some(code),
563:             reason: Some(reason),
564:             post_state_digest: None,
565:             verified_defect: None,
566:             event_id: None,
567:         }
568:     }
569: }
