571: /// Helper to build a 3-vertex directed cycle constraint problem encoding:
572: /// det = prod_diff - lin_corr.
573: pub fn build_mub6_det_cycle(
574:     a: BigRational,
575:     b: BigRational,
576:     c: BigRational,
577:     d: BigRational,
578: ) -> SymbolGameProblem {
579:     let prod_diff = &a * &d - &b * &c;
580:     let lin_corr = (&a - &b) + (&d - &c);
581:     let _det = &prod_diff - &lin_corr;
582: 
583:     let vertices = vec!["origin".to_string(), "mid".to_string(), "end".to_string()];
584:     let edges = vec![
585:         ProblemEdge {
586:             u: "origin".to_string(),
587:             v: "mid".to_string(),
588:             weight: BigRational::from_integer(BigInt::from(1)),
589:         },
590:         ProblemEdge {
591:             u: "mid".to_string(),
592:             v: "end".to_string(),
593:             weight: BigRational::from_integer(BigInt::from(1)),
594:         },
595:         ProblemEdge {
596:             u: "end".to_string(),
597:             v: "origin".to_string(),
598:             weight: BigRational::from_integer(BigInt::from(1)),
599:         },
600:     ];
601:     let initial_claims = vec![prod_diff, -lin_corr, BigRational::zero()];
602: 
603:     SymbolGameProblem::new(
604:         format!("MUB6_DET_CYCLE_a{}_b{}_c{}_d{}", a, b, c, d),
605:         vertices,
606:         edges,
607:         initial_claims,
608:     )
609:     .expect("Valid 3-cycle problem")
610: }
